import React from "react";
import { Link } from "react-router-dom";

const dateTime = (utcDate) => {
  if (!utcDate) return "";
  const date = new Date(utcDate);
  return date.toLocaleString("ru-RU", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
};

const getOutcomeColor = (outcome) => {
  if (outcome === "Win Home")
    return { text: "Прогноз: П1", colorClasses: "bg-green-600 text-white" };
  if (outcome === "Win Away")
    return {
      text: "Прогноз: П2",
      colorClasses: "bg-red-600 text-white",
    };
  if (outcome === "Draw")
    return {
      text: "Прогноз: X",
      colorClasses: "bg-yellow-500 text-black",
    };
  return null;
};

function MatchItem({ match }) {
  const predictionData = match.prediction
    ? getOutcomeColor(match.prediction.outcome)
    : null;

  // Вспомогательная функция для отрисовки логотипа или заглушки
  const renderTeamLogo = (team) => {
    const logoSrc = team.logo || team.logo_url;
    if (logoSrc) {
      return (
        <img
          src={logoSrc}
          alt={team.name}
          className="h-16 w-16 object-contain mb-1"
          onError={(e) => {
            // Если картинка не загрузилась, заменяем её на заглушку
            e.target.style.display = "none";
            e.target.nextSibling.style.display = "flex";
          }}
        />
      );
    }
    return null;
  };

  const renderPlaceholder = (name) => (
    <div
      className="h-16 w-16 bg-gray-800 rounded-full flex items-center justify-center mb-1 overflow-hidden border border-gray-700"
      style={match.homeTeam.logo ? { display: "none" } : { display: "flex" }}
    >
      <span className="text-xl font-bold text-gray-500">
        {name.substring(0, 1)}
      </span>
    </div>
  );

  return (
    <Link
      to={`/match/${match.id}`}
      className="block bg-gray-900 rounded-lg shadow-xl border border-gray-800 overflow-hidden
                 transform hover:-translate-y-1 hover:border-gray-600 transition-all duration-300 ease-in-out"
    >
      <div className="p-4 md:p-5 flex flex-col h-full relative">
        {/* Декоративная полоска слева */}
        <div className="absolute top-0 left-0 w-1 h-full bg-red-600 opacity-75"></div>

        <div className="pl-3">
          <div className="flex justify-around items-center mb-3">
            {/* Команда Хозяев */}
            <div className="flex flex-col items-center text-center w-2/5">
              {renderTeamLogo(match.homeTeam)}
              {renderPlaceholder(match.homeTeam.name)}
              <span className="text-sm font-semibold text-white truncate w-full mt-1">
                {match.homeTeam.name}
              </span>
            </div>

            <span className="text-2xl font-bold text-gray-700 italic">VS</span>

            {/* Команда Гостей */}
            <div className="flex flex-col items-center text-center w-2/5">
              {renderTeamLogo(match.awayTeam)}
              {renderPlaceholder(match.awayTeam.name)}
              <span className="text-sm font-semibold text-white truncate w-full mt-1">
                {match.awayTeam.name}
              </span>
            </div>
          </div>

          {/* Блок прогноза */}
          {predictionData && (
            <div className="my-3 text-center bg-black/20 py-2 rounded-md border border-white/5">
              <div className="flex flex-col gap-1 items-center">
                <span
                  className={`px-4 py-1 text-[10px] uppercase font-black rounded-full shadow-sm ${predictionData.colorClasses}`}
                >
                  {predictionData.text}
                </span>
                <span className="text-gray-400 text-xs font-medium">
                  Ожидаемый счет:{" "}
                  <span className="text-white">
                    {match.prediction.exact_score}
                  </span>
                </span>
              </div>
            </div>
          )}

          {/* Результат матча (если завершен) */}
          {match.status === "FINISHED" && (
            <div className="text-center my-2">
              <span className="text-2xl font-black text-yellow-500 tracking-widest">
                {match.score.homeTeam} : {match.score.awayTeam}
              </span>
            </div>
          )}

          {!predictionData && match.status !== "FINISHED" && (
            <div className="my-3 h-10 flex items-center justify-center">
              <span className="text-gray-600 text-xs animate-pulse">
                Анализ данных...
              </span>
            </div>
          )}

          <div className="mt-auto text-center text-[10px] text-gray-500 pt-3 border-t border-gray-800 uppercase tracking-widest">
            {dateTime(match.utcDate)}
          </div>
        </div>
      </div>
    </Link>
  );
}

export default MatchItem;
